#!/usr/bin/env bash
# Run an Android x86_64 binary on this host without booting Android: a rootless
# user+mount+pid namespace with the extracted image's /system, the flattened
# /apex (out/root/apex, from tools/flatten-apex.sh), /vendor from
# out/vendor-overlay, and a /linkerconfig generated by the image's own
# linkerconfig, so vendor libraries load in the real sphal namespace.
#
#   gpu/test/run-bionic.sh [-s] [-v extra-vendor-dir] [-e VAR=val] -- /data/gputest/prog args...
#
# -s also starts servicemanager (private binderfs) and our allocator service,
# with the hal lane's libhaltest_shim.so preloaded for properties
# (LINUXAPK_PROPS="name=value;...").
#
# out/gpu/build/test is visible at /data/gputest (the linkerconfig [system]
# section, like a platform binary; /data/local/tmp would be "unrestricted"). There is no init and no
# property service: properties read as empty (see propshim.c). Anything that
# needs binder services (libui/AHardwareBuffer allocation, ANGLE's EGL init)
# blocks here; test that in a session. TIMEOUT=<s> (default 300) kills the run.
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
repo=$(cd "$here/../.." && git rev-parse --path-format=absolute --git-common-dir | xargs dirname)
out=${OUT:-$repo/out}

if [[ ${1:-} != --inner ]]; then
  [[ -d $out/root/apex/com.android.runtime ]] || "$repo/tools/flatten-apex.sh" "$out/img" "$out/root/apex"
  mkdir -p "$out/gpu/run"
  export BIONIC_ROOT
  BIONIC_ROOT=$(mktemp -d "$out/gpu/run/root.XXXXXX")
  # SIGKILL on timeout: unshare does not forward SIGTERM, but --kill-child
  # takes the whole pid namespace down when unshare dies.
  rc=0
  timeout -s KILL "${TIMEOUT:-300}" \
    unshare --user --map-root-user --mount --pid --fork --kill-child -- "$0" --inner "$@" || rc=$?
  rmdir "$BIONIC_ROOT" 2>/dev/null || true
  ((rc == 137)) && echo "run-bionic: killed after ${TIMEOUT:-300}s" >&2
  exit $rc
fi
shift

extra_vendor=() envs=() services=0
while [[ $# -gt 0 ]]; do
  case $1 in
    -s)
      services=1
      shift
      ;;
    -v)
      extra_vendor+=("$2")
      shift 2
      ;;
    -e)
      envs+=("$2")
      shift 2
      ;;
    --)
      shift
      break
      ;;
    *) break ;;
  esac
done

mount --make-rprivate /
R=$BIONIC_ROOT
mount -t tmpfs -o mode=0755 root "$R"
mkdir -p "$R"/{system,vendor,apex,linkerconfig,dev,proc,sys,data/gputest,tmp,product,system_ext,odm}

ro_bind() {
  mount --bind "$1" "$2"
  mount -o remount,bind,ro "$2"
}
ro_bind "$out/img/system/system" "$R/system"
ro_bind "$out/img/system_ext" "$R/system_ext"
ro_bind "$out/img/product" "$R/product"
ro_bind "$out/root/apex" "$R/apex"
if ((${#extra_vendor[@]})); then
  lower=$(
    IFS=:
    echo "${extra_vendor[*]}"
  ):$out/vendor-overlay
  mount -t overlay overlay -o "ro,lowerdir=$lower" "$R/vendor"
else
  ro_bind "$out/vendor-overlay" "$R/vendor"
fi
mount --bind "$out/gpu/build/test" "$R/data/gputest"
mount -t tmpfs tmp "$R/tmp"
mount -t tmpfs linkerconfig "$R/linkerconfig"
mount -t tmpfs -o mode=0755 dev "$R/dev"
for n in null zero full random urandom udmabuf; do
  [[ -e /dev/$n ]] || continue
  touch "$R/dev/$n"
  mount --bind "/dev/$n" "$R/dev/$n"
done
# Render nodes only (no card*/KMS).
mkdir -p "$R/dev/dri"
for n in /dev/dri/renderD*; do
  [[ -e $n ]] || continue
  touch "$R$n"
  mount --bind "$n" "$R$n"
done
if ((services)); then
  # A private binderfs, plus the hal lane's test shim (props, selinux, logs).
  mkdir -p "$R/dev/binderfs"
  mount -t binder binder "$R/dev/binderfs"
  for b in binder hwbinder vndbinder; do ln -s "binderfs/$b" "$R/dev/$b"; done
  shim=$out/hal-build/tests/libhaltest_shim.so
  [[ -f $shim ]] || {
    echo "run-bionic: -s needs $shim (hal/build.sh)" >&2
    exit 1
  }
  mkdir -p "$R/data/local/tmp"
  cp "$shim" "$R/data/local/tmp/"
fi
mount -t proc proc "$R/proc"
# Host safety (docs/NOTES.md): never expose host /sys wholesale. A tmpfs /sys
# with read-only binds of what libdrm/Mesa read: each render node's PCI
# device dir (vendor/device/revision/uevent), /sys/dev/char links to them,
# and CPU topology.
mount -t tmpfs -o mode=0755 sys "$R/sys"
mkdir -p "$R/sys/dev/char"
for n in /dev/dri/renderD*; do
  [[ -e $n ]] || continue
  majmin=$(printf '%d:%d' "0x$(stat -c %t "$n")" "0x$(stat -c %T "$n")")
  node=$(readlink -f "/sys/dev/char/$majmin") # .../<pci dev>/drm/renderD128
  pcidev=${node%/drm/*}
  mkdir -p "$R$pcidev"
  ro_bind "$pcidev" "$R$pcidev"
  ln -s "$node" "$R/sys/dev/char/$majmin"
done
mkdir -p "$R/sys/devices/system/cpu"
ro_bind /sys/devices/system/cpu "$R/sys/devices/system/cpu"
mount --rbind "$R/sys" "$R/sys"
mount -o remount,bind,ro "$R/sys"
# Top-level symlinks from the system-as-root image (/bin, /etc, ...).
for e in "$out/img/system"/*; do
  n=$(basename "$e")
  [[ -L $e && ! -e $R/$n ]] && cp -P "$e" "$R/$n"
done

cd "$R"
pivot_root . .
umount -l .
cd /

for v in $(compgen -e); do unset "$v"; done
export PATH=/system/bin:/apex/com.android.runtime/bin ANDROID_ROOT=/system \
  ANDROID_DATA=/data ANDROID_ART_ROOT=/apex/com.android.art \
  ANDROID_I18N_ROOT=/apex/com.android.i18n ANDROID_TZDATA_ROOT=/apex/com.android.tzdata
for e in "${envs[@]}"; do export "${e?}"; done

# Same as init does at boot ("linkerconfig --target /linkerconfig").
/apex/com.android.runtime/bin/linkerconfig --target /linkerconfig >/dev/null || true

if ((services)); then
  # servicemanager and our allocator, as in hal/tests/run-android.sh.
  export LD_PRELOAD=/data/local/tmp/libhaltest_shim.so
  /system/bin/servicemanager &
  for _ in $(seq 50); do
    [[ -e /dev/binderfs/binder ]] && break
    sleep 0.1
  done
  sleep 0.3
  /vendor/bin/hw/android.hardware.graphics.allocator-service.linuxapk &
  sleep 0.5
fi
exec "$@"
